TLM.f("Sancti/01-25r",{"officium":"In Conversione S. Pauli Apostoli","rule":["ex Sancti/06-30;","Gloria","no Credo","Prefatio=Apostolis","Sub unica conclusione"],"ruleInherited":["Evangelium non appropriatum","ex C1;","Gloria","CredoDA","Prefatio=Apostolis","Sub unica concl","Psalmi Dominica","Antiphonas horas","Psalm5 Vespera=116","Psalm5 Vespera3=138"],"fallback":"Sancti/06-30","from":{"GradualeP":"Sancti/06-30"},"sections":{"Introitus":[{"k":"ref","la":"2 Tim 1:12"},{"k":"text","la":"Scio, cui crédidi, et certus sum, quia potens est depósitum meum serváre in illum diem, justus judex."},{"k":"ref","la":"Ps 138:1-2"},{"k":"text","la":"Dómine, probásti me et cognovísti me: tu cognovísti sessiónem meam et resurrectiónem meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Scio, cui crédidi, et certus sum, quia potens est depósitum meum serváre in illum diem, justus judex."}],"Oratio":[{"k":"text","la":"Deus, qui univérsum mundum beáti Pauli Apóstoli prædicatióne docuísti: da nobis, quǽsumus; ut, qui ejus hódie Conversiónem cólimus, per ejus ad te exémpla gradiámur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Actuum Apostolórum"},{"k":"ref","la":"Act 9:1-22"},{"k":"text","la":"In diébus illis: Saulus adhuc spirans minárum et cædis in discípulos Dómini, accés sit ad príncipem sacerdótum, et pétiit ab eo epístolas in Damáscum ad synagógas: ut, si quos invenísset hujus viæ viros ac mulíeres, vinctos perdúceret in Jerúsalem. Et cum iter fáceret, cóntigit, ut appropinquáret Damásco: et súbito circumfúlsit eum lux de cœlo. Et cadens in terram, audívit vocem dicéntem sibi: Saule, Saule, quid me perséqueris? Qui dixit: Quis es, Dómine? Et ille: Ego sum Jesus, quem tu perséqueris: durum est tibi contra stímulum calcitráre. Et tremens ac stupens, dixit: Dómine, quid me vis fácere? Et Dóminus ad eum: Surge et ingrédere civitátem, et ibi dicétur tibi, quid te opórteat fácere. Viri autem illi, qui comitabántur cum eo, stabant stupefácti, audiéntes quidem vocem, néminem autem vidéntes. Surréxit autem Saulus de terra, apertísque óculis nihil vidébat. Ad manus autem illum trahéntes, introduxérunt Damáscum. Et erat ibi tribus diébus non videns, et non manducávit neque bibit. Erat autem quidam discípulus Damásci, nómine Ananías: et dixit ad illum in visu Dóminus: Ananía. At ille ait: Ecce ego, Dómine. Et Dóminus ad eum: Surge et vade in vicum, qui vocátur Rectus: et quære in domo Judæ Saulum nómine Tarsénsem: ecce enim orat. Et vidit virum, Ananíam nómine, intrœúntem et imponéntem sibi manus, ut visum recipiat. Respóndit autem Ananías: Dómine, audívi a multis de viro hoc, quanta mala fécerit sanctis tuis in Jerúsalem: et hic habet potestátem a princípibus sacerdótum alligándi omnes, qui ínvocant nomen tuum. Dixit autem ad eum Dóminus: Vade, quóniam vas electiónis est mihi iste, ut portet nomen meum coram géntibus et régibus et fíliis Israël. Ego enim osténdam illi, quanta opórteat eum pro nómine meo pati. Et ábiit Ananías et introívit in domum: et impónens ei manus, dixit: Saule frater, Dóminus misit me Jesus, qui appáruit tibi in via, qua veniébas, ut vídeas et impleáris Spíritu Sancto. Ei conféstim cecidérunt ab óculis ejus tamquam squamæ, et visum recépit: et surgens baptizátus est. Et cum accepísset cibum, confortátus est. Fuit autem cum discípulis, qui erant Damásci, per dies áliquot. Et contínuo in synagógis prædicábat Jesum, quóniam hic est Fílius Dei. Stupébant autem omnes, qui audiébant, et dicébant: Nonne hic est, qui expugnábat in Jerúsalem eos, qui invocábant nomen istud: et huc ad hoc venit, ut vinctos illos dúcere ad príncipes sacerdótum? Saulus autem multo magis convalescébat, et confundébat Judæos, qui habitábant Damásci, affírmans, quóniam hic est Christus."}],"Graduale":[{"k":"ref","la":"Gal 2:8; 2:9"},{"k":"text","la":"Qui operátus est Petro in apostolátum, operátus est et mihi inter gentes: et cognovérunt grátiam Dei, quæ data est mihi."},{"k":"text","la":"Grátia Dei in me vácua non fuit: sed grátia ejus semper in me manet.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Magnus sanctus Paulus, vas electiónis, vere digne est glorificándus, qui et méruit thronum duodécimum possídere. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 106:8"},{"k":"text","la":"Confiteántur Dómino misericórdiæ ejus. et mirabília ejus fíliis hóminum. Allelúja."},{"k":"text","la":"Sancte Paule Apóstole, prædicátor veritátis et doctor géntium, intercéde pro nobis. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Gal 2:8; 2:9"},{"k":"text","la":"Qui operátus est Petro in apostolátum, operátus est et mihi inter gentes: et cognovérunt grátiam Dei, quæ data est mihi."},{"k":"text","la":"Grátia Dei in me vácua non fuit: sed grátia ejus semper in me manet.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"text","la":"Tu es vas electiónis, sancte Paule Apóstole: vere digne es glorificándus."},{"k":"text","la":"Prædicátor veritátis et doctor géntium in fide et veritáte.","mark":"V"},{"k":"text","la":"Per te omnes gentes cognovérunt grátiam Dei.","mark":"V"},{"k":"text","la":"Intercéde pro nobis ad Deum, qui te elégit.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 19:27-29"},{"k":"text","la":"In illo témpore: Dixit Petrus ad Jesum: Ecce, nos relíquimus ómnia, et secúti sumus te: quid ergo erit nobis? Jesus autem dixit illis: Amen, dico vobis, quod vos, qui secúti estis me, in regeneratióne, cum séderit Fílius hóminis in sede majestátis suæ, sedébitis et vos super sedes duódecim, judicántes duódecim tribus Israël. Et omnis, qui relíquerit domum, vel fratres, aut soróres, aut patrem, aut matrem, aut uxórem, aut fílios, aut agros, propter nomen meum, céntuplum accípiet, et vitam ætérnam possidébit."}],"Offertorium":[{"k":"ref","la":"Ps 138:17"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."}],"Secreta":[{"k":"text","la":"Apóstoli tui Pauli précibus, Dómine, plebis tuæ dona sanctífica: ut, quæ tibi tuo grata sunt institúto, gratióra fiant patrocínio supplicántis."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 19:28-29"},{"k":"text","la":"Amen, dico vobis: quod vos, qui reliquístis ómnia et secúti estis me, céntuplum accipiétis, et vitam ætérnam possidébitis. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Sanctificáti, Dómine, salutári mystério: quǽsumus; ut nobis ejus non desit orátio, cujus nos donásti patrocínio gubernári."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Oratio":[{"k":"rubric","la":"Pro S. Petro"},{"k":"text","la":"Deus, qui beáto Petro Apóstolo tuo, collátis clávibus regni cœléstis, ligándi atque solvéndi pontifícium tradidísti: concéde; ut, intercessiónis ejus auxílio, a peccatórum nostrórum néxibus liberémur:"},{"k":"macro","name":"Qui vivis"}],"Commemoratio Secreta":[{"k":"rubric","la":"Pro S. Petro"},{"k":"text","la":"Ecclésiæ tuæ, quǽsumus, Dómine, preces et hóstias beáti Petri Apóstoli comméndet orátio: ut, quod pro illíus glória celebrámus, nobis prosit ad véniam."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Postcommunio":[{"k":"rubric","la":"Pro S. Petro"},{"k":"text","la":"Lætíficet nos, Dómine, munus oblátum: ut, sicut in Apóstolo tuo Petro te mirábilem prædicámus; sic per illum tuæ sumámus indulgéntiæ largitátem."},{"k":"macro","name":"Per Dominum"}]},"hr":{"5dcf5fbe3d311635":{"t":"2 Tim 1, 12, Ps 138, 1-2\n(2 Tim 1, 12) Znam komu sam vjerovao i uvjeren sam da on može sačuvati zaklad moj za onaj dan. (Ps 138, 1-2) Gospodine, ti si me kušao i spoznao, tebi je poznat moj počinak i moje uskrsnuće.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(2 Tim 1, 12) Znam komu sam vjerovao i uvjeren sam da on može sačuvati zaklad moj za onaj dan.","kn":"(2. Tim. 1, 12). Znam, komu sam vjerovao i uvjeren sam, da je kao pravedni sudac kadar poklad moj sačuvati za onaj dan. (Ps. 138, 1, 2). Gospodine, Ti si me kušao i spoznao; Tebi je poznat moj počinak i moje ustajanje. Slava Ocu... Znam...","knRef":"Kniewald 1942, str. 488–489 (snimka 245) (OCR)"},"e255751dc3e5f494":{"t":"<i>Pomolimo se</i>.\nBože, koji si čitavi svijet poučio propovijedanjem blaženoga Pavla apostola, daj nam, molimo, da mi koji danas slavimo njegovo obraćenje idemo k tebi po njegovu primjeru.","v":"∅ → per","kn":"Bože, koji si cio svijet poučio propovijedanjem blaženoga Pavla apostola, podaj, molimo, da se mi, koji danas svetkujemo njegovo obraćenje, približimo Tebi slijedeći njegov primjer, po G. n.","knRef":"Kniewald 1942, str. 488–489 (snimka 245) (OCR)"},"12b566b864ba22e4":{"t":"Bože, koji si blaženom Petru apostolu predao ključeve kraljevstva nebeskoga i time velikosvećeničku vlast vezanja i odrješivanja, daj da se po njegovu zagovoru izbavimo od veza naših grijeha.\n<i>Koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si blaženomu Petru, apostolu svome, dao ključeve kraljevstva nebeskoga i vrhovnu vlast vezati i razriješiti, podaj, da se po njegovu zagovoru izbavimo od naših grijeha.","knRef":"Kniewald 1942, str. 618–619 (snimka 310) (OCR)"},"8080dc75bb048eef":{"t":"Dj 9, 1-22\nČitanje Djela apostolskih. U one dane dok je Savao još uvijek bjesnio prijetnjama da će poklati Kristove učenike, pristupi velikom svećeniku i od njega zatraži pisma za zbornice u Damasku, da može dovesti svezane u Jeruzalem muževe i žene, koje nađe da pristaju uz ovu nauku. I na putu blizu Damaska najednom ga obasja svjetlost s neba, pade na zemlju i ču glas koji ga upita: Savle, Savle, zašto me progoniš? On odvrati: Tko si ti, Gospodine? A on će mu: Ja sam Isus kojega ti progoniš. Teško ti je ritati se protiv ostana. Tad dršćući i zapanjen upita: Gospodine, što hoćeš da činim? Gospodin mu odgovori: Ustani, pođi u grad i ondje će ti se kazati što trebaš činiti. A ljudi koji su s njim putovali začudili su se, jer su čuli glas, a nisu vidjeli nikoga. Savao ustane sa zemlje i otvorenih očiju nije vidio ništa. Zato su ga vodili za ruke i uveli u Damask. Ondje je bio tri dana slijep, nije jeo. ni pio. A u Damasku je bio učenik Ananija. Gospodin mu se ukaže i pozove ga: Ananija! A on odvrati: Evo me, Gospodine! A Gospodin njemu: Ustani i pođi u Ravnu ulicu i u kući Jude potraži Savla iz Tarza, jer on moli. (I Savao u viđenju vidje kako Ananija ulazi i polaže na njega ruke da progleda). Ananija odgovori: Gospodine, od mnogih sam čuo o tom čovjeku koliko je zla učinio tvojim svetima u Jeruzalemu. I od svećeničkih poglavara ima vlast da veže ovdje sve koji prizivaju tvoje ime. A Gospodin mu reče: Pođi, jer sam ga ja izabrao da moje ime ponese pred nevjernike, kraljeve i sinove Izraelove. Ja ću mu pokazati, koliko treba trpjeti za moje ime. Ananija pođe i uđe u kuću. I kada je položio na njega ruke Ananija reče: Brate Savle, Gospodin Isus, koji ti se ukazao na putu kojim si išao poslao me da progledaš i napuniš se Duha Svetoga. I spadnu kao ljuske s njegovih očiju i progleda. Ustane i krsti se. A kada je založio, okrijepi se. Ostane nekoliko dana s učenicima koji su bili u Damasku. I odmah je propovijedao u zbornicama da je Isus Božji Sin. Svi koji su ga čuli snebivali su se i pitali: Nije li ovaj u Jeruzalemu progonio sve koji su prizivali Isusa? I ovamo je došao da ih svezane vodi k svećeničkim poglavarima. A Savao je bio sve snažniji i zbunjivao Židove nastanjene u Damasku dokazujući da je Isus Božji Pomazanik. [napomena M.B.: u Radićevom prijevodu umjesto pojma \"ostan\", koji je preuzet od Šarića (1942.) koristi se \"žalac\". Ostan je dugačak štap s metalnim šiljkom koji služi tjeranju životinja. Umjesto glagola \"praćkati\" u oba prijevoda stavio sam \"ritati\". Značenje je identično i opisuje ponašanje domaće životinje.]","kn":"Čitanje Djela apostolskih (9, 1-22). U one dane Saveo, dok je još prijetnjama i pokoljem bijesnio na Gospodnje učenike, pristupi velikomu svećeniku i od njega zatraži pisma na zbornice u Dama sku da dovede vezane u Jeruzalem muževe i žene, ako’ nađe da pristaju uz ovu nauku. I na putu, kad se približavao Damasku, najednom ga obasja svjetlost s neba i pade na zemlju i ču glas, gdje mu go'^i- Savle, Savle, zašto me progoniš? 0.n upita. Tko si ti. Gospodine? A on; Ja sam Isus, kojega orari ™u odgovori: Ustani 1 uđi u judi, koja BOI s njim putovali, bili „su zapanjeni -e diLei\" ® nikoga. A Savao dioS 7 f ^ otvorenih očiju nije vi- ^ r : ™ke i uveli u Da- S?f Pio A 'I®\"'’-'® '^tdeći, niti je jeo, Damasku učenik Anandja. G^podin mu se ukaze i reče: Ananija! On reče: i u *^113 ^ Gospodin njemu: Ustani ni^ ^ traži u Judinoj kući Tarža- nriu /dt'\"’ ^ ^tđenju ugleda Ana- sledai f i polaze na njega ruke, da pro- SSh o odgovori: Gospodine, čuo sam od mnogah o tom čovjeku, koliko je zla učinio tvojim svetima u Jeruzalemu. I od svećeničkih poglavara on, nm vlast, da veže ovdje sve, koji tebe prizivaju. A Gospodin mu reče: Idi, jer mi je on izabrana posuda, da moje ime ponese pred nezna- kazatri®''''' ' Izraelove. A ja ću mu po kazati, koliko mora trpjeti za moje ime. I Ananija ode 1 uđe u kuću. I kad je metnuo na njega ruke LTm Jutu \"'“ti ti se ujj: dit k ' r I odmah spa- f JJ J očiju i progleda. I ustane ie nekJl-k'^’ i založio, okrijepio se. A ostao je nekoliko dana s učenicima, koji su bili u Da- u zbornicama propovijedao, da je Isus Sin Bozji. Svi, koji su ga čuli, snebivali u se 1 pitali: Nije li ovo onaj, koji je u Jeruzalemu udarao na one, koji su prizivali ovo ime. i došao je ovamo zato, da ih vezane vodi k svećeničkim poglavarima? A Savao je bio sve jači i zbunjavao je nastanjene Zidove u Damasku dokazujući, da je ovaj Krist. Xđa^ ’ ®'’'“ isao, poslao me je, da pro-","knRef":"Kniewald 1942, str. 488–489 (snimka 245) (OCR)"},"543bbb6ad3449652":{"kn":"(Gal. 2, 8, 9). Onaj, koji pomože Petru u apostolstvu, pomože i meni među poganima, i upoznaše milost Božju, koja je meni dana. (I. Kor. 15, 10). Milost Božja nije bila bez ploda u meni, nego milost njegova uvijek je sa mnom.\nZavlaka: Ti si izabrana posuda, sveti Pavle apostole, i doista je pravo, da Te slavimo, jer si propovjednik istine i učitelj naroda u vjeri i istini. Po Tebi su svi narodi upoznali milost Božju. Zagovaraj nas kod Boga, koji Te je odabrao.","knRef":"Kniewald 1942, str. 491"},"9c583f5745d0c082":{"t":"Mt 19, 27-29\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Petar Isusu: Evo, mi smo ostavili sve i pošli za tobom. Što će, dakle, biti s nama? Isus im odgovori: Zaista vam kažem kad u vrijeme preporoda bude Sin čovječji sjedio na prijestolju svoga veličanstva, i vi koji ste pošli za mnom sjedit ćete na dvanaest prijestolja i suditi dvanaest Izraelskih plemena. A svaki koji radi mene ostavi kuću, ili braću, ili sestre, ili oca, ili majku, ili ženu, ili djecu ili polja, primit će stoput više i imat će vječni život.","kn":"t Slijedi sveto evanđelje po Mateju (19, 27-29). U ono vrijeme reće Petar Isusu: Evo, mi smo ostavili sve i pošli za tobom. Sto će, dakle, biti s nama? Isus im odgovori: Zaista vam kažem, da kad u vrijeme preiraroda bude Sin čovječji sjedio na prijestolju svoga veličanstva, i vi, koji ste pošli Za mnom, sjedit ćete na dvanaest prijestolja i suditi dvanaest Izraelskih plemena. A svaki koji radi mene ostavi kuću ili braću Hi sestre ili oca ili majku ili ženu ili djecu ili polja, primit će stoput više i imat će vječni život.","knRef":"Kniewald 1942, str. 628–629 (snimka 315) (OCR)"},"8bade162dbdb175e":{"t":"Ps 138, 17\nNada sve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove.","kn":"(Ps. 138, 17). Veoma častim prijatelje Tvoje, Bože, silno se utvrdi kneževstvo njihovo!","knRef":"Kniewald 1942, str. 742–743 (snimka 372) (OCR)"},"f43c659e380d72b6":{"t":"Posveti, Gospodine, po molitvama svoga apostola Pavla darove svoga naroda, koji su ti mili jer si ih ustanovio, pa neka ti budu miliji po zagovoru našega zaštitnika.","kn":"Posveti, Gospodine, molitvama apostola svoga Pavla dare puka svoga, da ono, što Ti je ugodno, jer si to sam ustanovio, bude Tebi još ugodnije poradi njegova zagovora, po G. n. I. K.","knRef":"Kniewald 1942, str. 620–621 (snimka 311) (OCR)"},"0fe93625122c551c":{"t":"Molitva blaženoga Petra apostola neka preporuči, molimo, Gospodine, molitve i darove tvoje Crkve, da nama koristi za oproštenje što njemu na čast svetkujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, neka prošnje i žrtve Tvoje Crkve preporuči molitva blaženoga Petra Apostola, da nam uskoristi za oproštenje, što svetkujemo na njegovu slavu, po G. n.","knRef":"Kniewald 1942, str. 480–481 (snimka 241) (OCR)"},"fdbfd5e8960de5c2":{"t":"Uistinu je dostojno, i pravedno, pravo i spasonosno tebe, Gospodine, vječni Pastiru, smjerno moliti da stado svoje ne ostaviš, nego da ga po svojim blaženim apostolima neprestano štitiš i čuvaš, da njime ravnaju isti poglavari, koje si mu postavio na čelo kao pastire i namjesnike svoga djela. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno. Tebe, Gospodine, vječni Pastiru, smjerno moliti, da ne ostaviš svoga stada, nego’ da ga po blaženim svojim apostolima sveudiljnom zaštitom čuvaš, te Tvojim stadom upravljaju isti vođe, koje si Ti odredio da ga vode kao pastiri i namjesnici Tvoga djelovanja. I toga radi pjevamo pjesmu slave Tvoje s anđelima i s arkanđelima, s prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 618–619 (snimka 310) (OCR)"},"d76f89b9ab1556d0":{"t":"Mt 19, 28 i 29\nZaista vam kažem da ćete vi koji ste ostavili sve i pošli za mnom primiti stostruko i baštiniti život vječni.","kn":"(Mt. 19, 28, 29). Zaista vam kažem, da čete vi, koji ste sve ostavili 1 koji ste pošli za mnom, primiti stoput onoliko i baštinit ćete život vječni.","knRef":"Kniewald 1942, str. 620–621 (snimka 311) (OCR)"},"cd9242e62e1257e1":{"t":"Posvećeni, Gospodine, spasonosnom tajnom molimo, da nam ne bude uskraćena molitva onoga kojega si nam darovao kao zaštitnika i upravitelja."},"4dbe0d4385fb1374":{"t":"Neka nas, Gospodine, razveseli prikazani dar da po tvome apostolu Petru tako primimo tvoje obilno oproštenje kao što u njemu slavimo tvoja čudesa.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Neka nas obraduje. Gospodine, žrtvovani dar, te kao što veličamo čudesa Tvoja u Tvom apostolu Petru, takonam po njemu udijeli obilje Tvog ciproštenja, -po G. n.","knRef":"Kniewald 1942, str. 480–481 (snimka 241) (OCR)"},"13c7701f39f0da1a":{"t":"Gal 2, 8 i 9, 1 Kor 15, 10\n(Gal 2, 8 i 9) Onaj koji je pomagao Petru u apostolatu pomagao je i meni među narodima, tako da su upoznali milost Božju koja mi je dana. (1 Kor 15, 10) Milost Božja nije u meni bila neplodna, nego njegova milost trajno prebiva u meni.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nUistinu je dostojno da slavimo velikoga svetog Pavla, izabranu posudu, koji je zavrijedio da sjedne na dvanaesto prijestolje. <i>Aleluja</i>.","kn":"<i>Aleluja</i>, <i>aleluja</i>.\n(Gal. 2, 8, 9). Onaj, koji pomože Petru u apostolstvu, pomože i meni među poganima, i upoznaše milost Božju, koja je meni dana. (1. Kor. 15, 10). Milost Božja nije bila bez ploda u meni, nego milost njegova uvijek je sa mnom. Alcluja,’ aleluja. Velik si, sveti Pavle aposto^le, odabrana posudo; dostojno je, (ia Te slavimo, jer si zaslužio da zauzmeš dvanaesti prijesto, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 490–491 (snimka 246) (OCR)"}}});
